-- Staging pre-load (Supabase -> Aurora migration, vitana-aurora-staging only). Run BEFORE the DMS full load, on the
-- schema that the VTID-05803 path built (the package's native dump restore, or the migration replay), through
--   bash scripts/aws/staging-db-migration.sh pre-load --cluster vitana-aurora-staging
-- One Data API transaction: all or nothing. Re-runnable: every step only acts on what is still there.
--
-- Why: the DMS task truncates and reloads each table (TRUNCATE_BEFORE_LOAD), which PostgreSQL refuses for a table
-- that a foreign key references, and DMS cannot write pgvector columns. So, exactly as the production runbook
-- (aurora-cutover-vector-preload.sql), the load needs the vector columns as text and no foreign keys. Unlike the
-- production script, nothing is regenerated from an old snapshot: everything this file removes is first saved
-- from the live catalog into migration_audit, and staging-db-restore-saved.sql puts back exactly that.
--   1. Refuses to start if the vector extension is missing, or if an RLS policy or a trigger uses a vector column
--      (PostgreSQL cannot change the type under those).
--   2. Saves and drops every foreign key that touches a public table (pg_get_constraintdef). A foreign key from
--      public into auth is saved with references_auth = true and is never restored. That is owner decision R2
--      (VTID-05023, the same rule as the package's r2-exclude-auth-users-fks.sql): no public -> auth.users FK on Aurora.
--   3. Saves and drops the views and materialized views that depend on a vector column, directly or through another
--      view: definition, options (security_invoker, check_option), grants and comment.
--   4. Saves and drops the indexes on the vector columns (pg_get_indexdef).
--   5. Changes the 13 vector columns to text (values kept as their text form).
--   6. Asserts the end state, or raises and rolls everything back.
-- No row is read for anything else, changed or deleted; no table is truncated here.

-- 1. Guards. The extension's schema goes on this transaction's search_path.
DO $guard$ DECLARE s text; deps text; BEGIN SELECT n.nspname INTO s FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'vector'; IF s IS NULL THEN RAISE EXCEPTION 'staging pre-load: the vector extension is not installed; nothing changed'; END IF; PERFORM set_config('search_path', 'public, ' || quote_ident(s), true); SELECT string_agg(DISTINCT CASE d.classid WHEN 'pg_policy'::regclass THEN 'policy ' || (SELECT polname FROM pg_policy WHERE oid = d.objid) ELSE 'trigger ' || (SELECT tgname FROM pg_trigger WHERE oid = d.objid) END || ' on ' || x.tbl || '.' || x.col, ', ') INTO deps FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.tbl) AND a.attname = x.col JOIN pg_depend d ON d.refclassid = 'pg_class'::regclass AND d.refobjid = a.attrelid AND d.refobjsubid = a.attnum AND d.classid IN ('pg_policy'::regclass, 'pg_trigger'::regclass); IF deps IS NOT NULL THEN RAISE EXCEPTION 'staging pre-load: % use a vector column; nothing changed', deps; END IF; END $guard$;

-- Where the removed objects are kept until staging-db-restore-saved.sql puts them back.
CREATE SCHEMA IF NOT EXISTS migration_audit;
CREATE TABLE IF NOT EXISTS migration_audit.saved_foreign_keys (table_name text NOT NULL, constraint_name text NOT NULL, definition text NOT NULL, references_auth boolean NOT NULL, saved_at timestamptz NOT NULL DEFAULT now(), restored_at timestamptz, PRIMARY KEY (table_name, constraint_name));
CREATE TABLE IF NOT EXISTS migration_audit.saved_views (view_name text PRIMARY KEY, relkind text NOT NULL, depth integer NOT NULL, definition text NOT NULL, reloptions text[], grants text[] NOT NULL DEFAULT '{}', comment text, saved_at timestamptz NOT NULL DEFAULT now(), restored_at timestamptz);
CREATE TABLE IF NOT EXISTS migration_audit.saved_indexes (index_name text PRIMARY KEY, table_name text NOT NULL, definition text NOT NULL, saved_at timestamptz NOT NULL DEFAULT now(), restored_at timestamptz);

-- 2. Foreign keys that touch a public table (either side): saved, then dropped.
DO $fk$ DECLARE r record; BEGIN FOR r IN SELECT quote_ident(tn.nspname) || '.' || quote_ident(t.relname) AS tbl, c.conname, pg_get_constraintdef(c.oid) AS def, (tn.nspname = 'public' AND rn.nspname = 'auth') AS to_auth FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace tn ON tn.oid = t.relnamespace JOIN pg_class rt ON rt.oid = c.confrelid JOIN pg_namespace rn ON rn.oid = rt.relnamespace WHERE c.contype = 'f' AND (tn.nspname = 'public' OR rn.nspname = 'public') ORDER BY 1, 2 LOOP INSERT INTO migration_audit.saved_foreign_keys (table_name, constraint_name, definition, references_auth) VALUES (r.tbl, r.conname, r.def, r.to_auth) ON CONFLICT (table_name, constraint_name) DO UPDATE SET definition = EXCLUDED.definition, references_auth = EXCLUDED.references_auth, saved_at = now(), restored_at = NULL; EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.tbl, r.conname); END LOOP; END $fk$;

-- 3. Views and materialized views on a vector column (and views on those): saved with their depth, then dropped deepest first.
DO $views$ DECLARE r record; BEGIN CREATE TEMP TABLE vpl_views ON COMMIT DROP AS WITH RECURSIVE cols AS (SELECT a.attrelid AS relid, a.attnum FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.tbl) AND a.attname = x.col), dep(oid, depth) AS (SELECT DISTINCT w.ev_class, 1 FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN cols ON d.refobjid = cols.relid AND d.refobjsubid = cols.attnum WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass AND w.ev_class <> cols.relid UNION SELECT w.ev_class, dep.depth + 1 FROM dep JOIN pg_depend d ON d.refobjid = dep.oid AND d.refclassid = 'pg_class'::regclass AND d.classid = 'pg_rewrite'::regclass JOIN pg_rewrite w ON w.oid = d.objid WHERE w.ev_class <> dep.oid AND dep.depth < 32) SELECT oid, max(depth) AS depth FROM dep GROUP BY oid; FOR r IN SELECT v.oid, quote_ident(n.nspname) || '.' || quote_ident(c.relname) AS name, c.relkind::text AS kind, v.depth, rtrim(btrim(pg_get_viewdef(v.oid)), ';') AS def, c.reloptions, coalesce((SELECT array_agg(format('GRANT %s ON %s TO %s', g.privilege_type, quote_ident(n.nspname) || '.' || quote_ident(c.relname), CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(g.grantee)) END) ORDER BY g.grantee, g.privilege_type) FROM aclexplode(c.relacl) g WHERE g.grantee <> c.relowner), '{}') AS grants, obj_description(v.oid, 'pg_class') AS cmt FROM vpl_views v JOIN pg_class c ON c.oid = v.oid JOIN pg_namespace n ON n.oid = c.relnamespace ORDER BY v.depth DESC, 2 LOOP INSERT INTO migration_audit.saved_views (view_name, relkind, depth, definition, reloptions, grants, comment) VALUES (r.name, r.kind, r.depth, r.def, r.reloptions, r.grants, r.cmt) ON CONFLICT (view_name) DO UPDATE SET relkind = EXCLUDED.relkind, depth = EXCLUDED.depth, definition = EXCLUDED.definition, reloptions = EXCLUDED.reloptions, grants = EXCLUDED.grants, comment = EXCLUDED.comment, saved_at = now(), restored_at = NULL; EXECUTE format('DROP %s %s', CASE r.kind WHEN 'm' THEN 'MATERIALIZED VIEW' ELSE 'VIEW' END, r.name); END LOOP; END $views$;

-- 4. Indexes on the vector columns: saved, then dropped.
DO $idx$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT quote_ident(n.nspname) || '.' || quote_ident(i.relname) AS name, quote_ident(n.nspname) || '.' || quote_ident(t.relname) AS tbl, pg_get_indexdef(i.oid) AS def FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.tbl) AND a.attname = x.col JOIN pg_depend d ON d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.refobjid = a.attrelid AND d.refobjsubid = a.attnum JOIN pg_class i ON i.oid = d.objid AND i.relkind = 'i' JOIN pg_class t ON t.oid = a.attrelid JOIN pg_namespace n ON n.oid = i.relnamespace LOOP INSERT INTO migration_audit.saved_indexes (index_name, table_name, definition) VALUES (r.name, r.tbl, r.def) ON CONFLICT (index_name) DO UPDATE SET definition = EXCLUDED.definition, saved_at = now(), restored_at = NULL; EXECUTE format('DROP INDEX %s', r.name); END LOOP; END $idx$;

-- 5. The vector columns as text, for the load. Only while they are not text yet.
DO $text$ DECLARE r record; BEGIN FOR r IN SELECT x.tbl, x.col FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) JOIN information_schema.columns c ON c.table_schema = 'public' AND c.table_name = x.tbl AND c.column_name = x.col WHERE c.data_type <> 'text' LOOP EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I TYPE text USING %I::text', r.tbl, r.col, r.col); END LOOP; END $text$;

-- 6. End state, or roll everything back.
DO $assert$ DECLARE bad text; BEGIN SELECT string_agg(x.tbl || '.' || x.col || ' is ' || coalesce(c.data_type, 'missing'), ', ') INTO bad FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) LEFT JOIN information_schema.columns c ON c.table_schema = 'public' AND c.table_name = x.tbl AND c.column_name = x.col WHERE c.data_type IS DISTINCT FROM 'text'; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging pre-load: columns not staged as text (%); rolled back', bad; END IF; SELECT string_agg(c.conname, ', ') INTO bad FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace tn ON tn.oid = t.relnamespace JOIN pg_class rt ON rt.oid = c.confrelid JOIN pg_namespace rn ON rn.oid = rt.relnamespace WHERE c.contype = 'f' AND (tn.nspname = 'public' OR rn.nspname = 'public'); IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging pre-load: foreign keys left (%); rolled back', bad; END IF; SELECT string_agg(view_name, ', ') INTO bad FROM migration_audit.saved_views WHERE restored_at IS NULL AND to_regclass(view_name) IS NOT NULL; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging pre-load: views left (%); rolled back', bad; END IF; END $assert$;
